import{_ as e,c as i,o as t,a2 as r}from"./chunks/framework.B3iQLowF.js";const o=JSON.parse('{"title":"QuickLinker-ZeroRPM | Mohanpathi Portfolio","description":"Enterprise-grade software project by Mohanpathi - System Architect & Full-Stack Engineer","frontmatter":{"layout":"doc","title":"QuickLinker-ZeroRPM"},"headers":[],"relativePath":"docs/quicklinker-zeroRPM/overview.md","filePath":"docs/quicklinker-zeroRPM/overview.md","lastUpdated":1741723016000}');const a=e({name:"docs/quicklinker-zeroRPM/overview.md"},[["render",function(e,o,a,s,n,l){return t(),i("div",null,o[0]||(o[0]=[r('<h1 id="quicklinker-zerorpm" tabindex="-1">QuickLinker-ZeroRPM <a class="header-anchor" href="#quicklinker-zerorpm" aria-label="Permalink to &quot;QuickLinker-ZeroRPM&quot;">​</a></h1><p><strong>A High-Performance URL Shortener</strong><br><em>Zero infrastructure cost, infinite scalability</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>QuickLinker-ZeroRPM is a URL shortener engineered to handle enterprise-scale traffic—targeting 100,000 requests per minute (RPM)—at zero infrastructure cost. Built with Node.js, Express, SQLite, and Redis, it leverages lightweight technologies to deliver a scalable, resilient system hosted on Oracle’s Always Free Tier (4 Arm cores, 24 GB RAM). This project challenges the notion that SQLite is only for small apps, using optimizations and caching to push its limits, while exploring cost-effective alternatives to traditional databases like PostgreSQL and MongoDB.</p><h3 id="project-motivation" tabindex="-1">Project Motivation <a class="header-anchor" href="#project-motivation" aria-label="Permalink to &quot;Project Motivation&quot;">​</a></h3><p>The project pursues four core goals:</p><ul><li><strong>Cost Efficiency</strong>: Achieve $0/month infrastructure costs using SQLite on a free VM, minimizing resource overhead.</li><li><strong>Scalability</strong>: Support 100,000+ RPM with Redis caching and SQLite optimizations, reducing database load.</li><li><strong>Reliability</strong>: Ensure 99.9% uptime through replication (LiteFS) and chaos testing (Chaos Mesh).</li><li><strong>Learning</strong>: Provide a case study on scaling SQLite for production, balancing cost and complexity for system engineers.</li></ul><p>This isn’t just a tool—it’s an experiment in rethinking system design with minimal resources.</p><h2 id="why-sqlite-over-postgresql-and-mongodb" tabindex="-1">Why SQLite Over PostgreSQL and MongoDB? <a class="header-anchor" href="#why-sqlite-over-postgresql-and-mongodb" aria-label="Permalink to &quot;Why SQLite Over PostgreSQL and MongoDB?&quot;">​</a></h2><p>QuickLinker-ZeroRPM starts with PostgreSQL in Phase 1 for its ACID compliance and simplicity, then pivots to SQLite for cost savings. MongoDB was considered but sidelined—here’s why:</p><ul><li><strong>SQLite Preference</strong>: <ul><li>Embedded, serverless, and lightweight, SQLite runs within the app on a single file, slashing setup and resource costs. With Redis caching 99% of reads, SQLite handles the remaining 1,990 operations per minute (990 reads, 1,000 writes), well within its tuned capacity of 80,000 inserts/second (<a href="https://phiresky.github.io/blog/2020/sqlite-performance-tuning/" target="_blank" rel="noreferrer">SQLite Performance Tuning</a>).</li><li>Migration from PostgreSQL to SQLite is seamless due to shared SQL syntax, unlike MongoDB’s document model.</li></ul></li><li><strong>PostgreSQL Strengths</strong>: Offers strong consistency and vertical scaling for Phase 1’s 100 req/s target, but its server-based nature increases resource demands compared to SQLite.</li><li><strong>MongoDB Drawbacks</strong>: Excels in read-heavy caching, but Redis already offloads reads. MongoDB’s eventual consistency risks duplicate short codes, and its high-availability setup (3-node replica set) conflicts with the $0 cost goal.</li></ul><p>SQLite, paired with LiteFS for replication, aligns with the project’s cost-performance trade-offs.</p><h2 id="technical-highlights" tabindex="-1">Technical Highlights <a class="header-anchor" href="#technical-highlights" aria-label="Permalink to &quot;Technical Highlights&quot;">​</a></h2><ul><li><strong>Zero-Cost Hosting</strong>: Deploys on Oracle’s free Arm-based VMs, leveraging 4 cores and 24 GB RAM.</li><li><strong>SQLite Scalability</strong>: Achieves 100,000 RPM with Write-Ahead Logging (WAL), synchronous normal mode, and Redis caching (<a href="https://news.ycombinator.com/item?id=35547819" target="_blank" rel="noreferrer">Hacker News Discussion</a>).</li><li><strong>Resilience</strong>: Uses LiteFS for SQLite replication across nodes (<a href="https://github.com/superfly/litefs" target="_blank" rel="noreferrer">LiteFS GitHub</a>) and Chaos Mesh for fault testing.</li><li><strong>Phased Evolution</strong>: <ol><li><strong>Phase 1</strong>: Minimum Viable Scaling with PostgreSQL, then SQLite, targeting 100 req/s.</li><li><strong>Phase 2</strong>: Analytics Pipeline with Kafka and TimescaleDB.</li><li><strong>Phase 3</strong>: Resilience Engineering with multi-node replication.</li></ol></li></ul><h2 id="expected-outcomes" tabindex="-1">Expected Outcomes <a class="header-anchor" href="#expected-outcomes" aria-label="Permalink to &quot;Expected Outcomes&quot;">​</a></h2><ul><li>Handle <strong>100,000+ RPM</strong> on a single SQLite instance with caching.</li><li>Maintain <strong>$0/month costs</strong> on free-tier infrastructure.</li><li>Deliver a case study on: <ul><li>Scaling SQLite beyond traditional limits.</li><li>Optimizing cost-to-complexity ratios.</li><li>Efficient caching for high-traffic services.</li></ul></li></ul><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><p>Dive deeper:</p><ul><li><strong><a href="./project-overview/introduction">Project Details</a></strong>: Explore motivation and goals.</li><li><strong><a href="./technical-architecture/phase-1/">Technical Architecture</a></strong>: Review phased implementation.</li><li><strong><a href="./findings/feasibility">Findings</a></strong>: See research insights.</li><li><strong><a href="./">References</a></strong>: Cited resources.</li></ul><h2 id="get-involved" tabindex="-1">Get Involved <a class="header-anchor" href="#get-involved" aria-label="Permalink to &quot;Get Involved&quot;">​</a></h2><p>Check the <a href="https://github.com/your-repo/quicklinker-zerorpm" target="_blank" rel="noreferrer">GitHub repository</a> (update with your URL) or explore the sections above. This project invites you to rethink system design with efficiency at its core.</p>',21)]))}]]);export{o as __pageData,a as default};
